#include <iostream>
using namespace std;

void bubbleSort(int arr[], int n) {
    for (int pass = 1; pass <= n - 1; pass++) {
        bool swapped = false;
        for (int j = 0; j < n - pass; j++) {
            if (arr[j] > arr[j + 1]) {
                swap(arr[j], arr[j + 1]);      // std::swap
                swapped = true;
            }
        }
        if (!swapped) break;                   // already sorted
    }
}

void printArray(int arr[], int n) {
    for (int i = 0; i < n; i++) cout << arr[i] << " ";
    cout << endl;
}

int main() {
    int a[] = {5, 1, 4, 2, 8};
    int n = sizeof(a) / sizeof(a[0]);          // number of elements = 5
    bubbleSort(a, n);
    printArray(a, n);                          // 1 2 4 5 8
    return 0;
}

void selectionSort(int arr[], int n) {
    for (int i = 0; i < n - 1; i++) {
        int minIndex = i;
        for (int j = i + 1; j < n; j++) {
            if (arr[j] < arr[minIndex])
                minIndex = j;
        }
        if (minIndex != i)
            swap(arr[i], arr[minIndex]);
    }
}

void insertionSort(int arr[], int n) {
    for (int i = 1; i < n; i++) {
        int key = arr[i];
        int j = i - 1;
        while (j >= 0 && arr[j] > key) {
            arr[j + 1] = arr[j];     // shift right
            j--;
        }
        arr[j + 1] = key;            // insert in the gap
    }
}

