    for (int pass = 1; pass < n; pass++) {
        bool swapped = false;
        for (int j = 0; j < n - pass; j++) {
            comparisons++;
            if (a[j] > a[j + 1]) {
                swap(a[j], a[j + 1]);
                swaps++;
                swapped = true;
            }
        }
        if (!swapped) break;
    }
    cout << "Comparisons: " << comparisons << ", Swaps: " << swaps << endl;
