struct Student { int roll; string name; int marks; };

void meritSort(Student s[], int n) {               // descending by marks
    for (int i = 1; i < n; i++) {
        Student key = s[i];
        int j = i - 1;
        while (j >= 0 && s[j].marks < key.marks) {
            s[j + 1] = s[j];
            j--;
        }
        s[j + 1] = key;
    }
}

int main() {
    Student cls[] = {{1, "Aman", 78}, {2, "Priya", 92}, {3, "Rahul", 85}, {4,
"Sana", 92}};
    meritSort(cls, 4);
    for (int i = 0; i < 4; i++)
        cout << i + 1 << ". " << cls[i].name << " (" << cls[i].marks << ")"
<< endl;
}

